    "reglemente_ou_obligatoire": "Réglementé côté public : concours et statut de sapeur-pompier professionnel (Emploipublic). Autres cadres relevés : (a) SSIAP 3 (chef de service de sécurité incendie), 216 heures, 2 700 à 5 500 € selon MaFormation (14/08/2026), accès avec un diplôme de niveau 4 au minimum ou SSIAP 2 + 3 ans, plus PSC1/SST de moins de 2 ans et aptitude médicale de moins de 3 mois, CPF plafonné à 1 500 € (décret du 24/02/2026) ; (b) contrôleur technique de la construction : activité soumise à agrément ministériel ",
